  "inlineSchema": "// === Conexión y generador ===\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\n// === Roles ===\nenum Rol {\n  ADMIN\n  MECANICO\n  ASISTENTE\n  CHOFER\n  EMPRESA\n}\n\nenum TipoMantenimiento {\n  PREVENTIVO\n  CORRECTIVO\n  LEGAL_ITV\n  EXTRAS\n}\n\nenum EstadoCita {\n  SOLICITADA\n  ACEPTADA\n  EN_PROGRESO\n  TERMINADA\n}\n\nenum PrioridadNotificacion {\n  BAJA\n  MEDIA\n  ALTA\n}\n\nenum EstadoNotificacion {\n  PENDIENTE\n  LEIDA\n}\n\nmodel Usuario {\n  id             Int      @id @default(autoincrement())\n  nombreCompleto String\n  correo         String   @unique\n  hashClave      String\n  rol            Rol      @default(ASISTENTE)\n  creadoEn       DateTime @default(now())\n  actualizadoEn  DateTime @updatedAt\n\n  // Si pertenece a una empresa\n  empresaId Int?\n  empresa   Empresa? @relation(fields: [empresaId], references: [id])\n\n  // Vehículos\n  vehiculosPropietario Vehiculo[] @relation(\"VehiculosPropietario\")\n  vehiculosCreados     Vehiculo[] @relation(\"VehiculosCreados\")\n\n  // Notificaciones recibidas\n  notificaciones Notificacion[]\n\n  // === NUEVO: Citas como cliente y como mecánico ===\n  citasComoCliente  CitaMantenimiento[] @relation(\"CitasCliente\")\n  citasComoMecanico CitaMantenimiento[] @relation(\"CitasMecanico\")\n}\n\nmodel Empresa {\n  id          Int        @id @default(autoincrement())\n  razonSocial String\n  ruc         String     @unique\n  creadoEn    DateTime   @default(now())\n  usuarios    Usuario[]\n  vehiculos   Vehiculo[]\n}\n\nmodel Vehiculo {\n  id     Int     @id @default(autoincrement())\n  placa  String  @unique\n  marca  String\n  modelo String\n  anio   Int\n  color  String\n  vin    String?\n\n  // propietario (obligatorio)\n  propietarioUsuarioId Int\n  propietario          Usuario @relation(\"VehiculosPropietario\", fields: [propietarioUsuarioId], references: [id])\n\n  // auditoría de creación (obligatorio)\n  creadoPorId Int\n  creadoPor   Usuario @relation(\"VehiculosCreados\", fields: [creadoPorId], references: [id])\n\n  // Pertenencia (opcional)\n  empresaId Int?\n  empresa   Empresa? @relation(fields: [empresaId], references: [id])\n\n  // Datos operativos\n  kms                       Int       @default(0)\n  proximoMantenimientoKm    Int?\n  proximoMantenimientoFecha DateTime?\n\n  creadoEn      DateTime @default(now())\n  actualizadoEn DateTime @updatedAt\n\n  // Relación con llantas\n  llantas Llanta[]\n\n  // === NUEVO: Citas de mantenimiento asociadas a este vehículo ===\n  citas CitaMantenimiento[]\n\n  // Notificaciones ligadas al vehículo (si aplica)\n  notificaciones Notificacion[]\n\n  @@index([empresaId])\n}\n\nmodel Llanta {\n  id               Int       @id @default(autoincrement())\n  vehiculoId       Int\n  vehiculo         Vehiculo  @relation(fields: [vehiculoId], references: [id])\n  posicion         String? // ej. \"DI-IZQ\", \"TR-DR\"\n  fechaInstalacion DateTime?\n  fechaVencimiento DateTime // usado por la regla de vencimiento\n  vidaUtilKm       Int? // si luego deseas calcular por km\n\n  creadoEn DateTime @default(now())\n\n  @@index([vehiculoId])\n  @@index([fechaVencimiento])\n}\n\nmodel CitaMantenimiento {\n  id             Int               @id @default(autoincrement())\n  tipo           TipoMantenimiento\n  comentario     String            @db.Text\n  estado         EstadoCita        @default(SOLICITADA)\n  programadaPara DateTime?\n  creadoEn       DateTime          @default(now())\n  actualizadoEn  DateTime          @updatedAt\n\n  // Relaciones\n  clienteId Int\n  cliente   Usuario @relation(\"CitasCliente\", fields: [clienteId], references: [id])\n\n  mecanicoId Int?\n  mecanico   Usuario? @relation(\"CitasMecanico\", fields: [mecanicoId], references: [id])\n\n  vehiculoId Int\n  vehiculo   Vehiculo @relation(fields: [vehiculoId], references: [id])\n\n  // Notificaciones relacionadas (opcional)\n  notificaciones Notificacion[]\n\n  @@index([clienteId])\n  @@index([mecanicoId, estado])\n  @@index([vehiculoId])\n}\n\nmodel Notificacion {\n  id        Int     @id @default(autoincrement())\n  usuarioId Int\n  usuario   Usuario @relation(fields: [usuarioId], references: [id])\n\n  vehiculoId Int?\n  vehiculo   Vehiculo? @relation(fields: [vehiculoId], references: [id])\n\n  citaId Int?\n  cita   CitaMantenimiento? @relation(fields: [citaId], references: [id])\n\n  mensaje   String\n  prioridad PrioridadNotificacion @default(MEDIA) // BAJA | MEDIA | ALTA\n  estado    EstadoNotificacion    @default(PENDIENTE) // PENDIENTE | LEIDA\n  creadoEn  DateTime              @default(now())\n\n  @@index([usuarioId, estado])\n  @@index([vehiculoId])\n  @@index([citaId])\n}\n",
